import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"B-705 L0 behavior invariants check (show only, never interrupt — RFC §6.2.7)","description":"","frontmatter":{},"headers":[],"relativePath":"acceptance-B705-L0-behavior.md","filePath":"acceptance-B705-L0-behavior.md"}'),i={name:"acceptance-B705-L0-behavior.md"};function r(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="b-705-l0-behavior-invariants-check-show-only-never-interrupt-—-rfc-§6-2-7" tabindex="-1">B-705 L0 behavior invariants check (show only, never interrupt — RFC §6.2.7) <a class="header-anchor" href="#b-705-l0-behavior-invariants-check-show-only-never-interrupt-—-rfc-§6-2-7" aria-label="Permalink to &quot;B-705 L0 behavior invariants check (show only, never interrupt — RFC §6.2.7)&quot;">​</a></h1><blockquote><p>Status: the code-side static audit is complete (recorded in this document); per-item real-machine verification belongs to the B-803 end-to-end walkthrough (run on the first Windows machine).</p></blockquote><h2 id="invariant-table" tabindex="-1">Invariant table <a class="header-anchor" href="#invariant-table" aria-label="Permalink to &quot;Invariant table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Invariant</th><th>Code guarantee</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td>L0 only shows state; a click drills down (to L2 or L3)</td><td><code>PinnedHostWindow.TileActivated</code> is the only click exit → <code>QuickPanelWindow.Toggle()</code> (L2); there is no other behavior entry</td><td>✅ audit passed</td></tr><tr><td>2</td><td>Produces no dialog, no Toast, no sound</td><td><code>PinnedHostWindow.cs</code> contains no Toast/ContentDialog/MessageBox/Sound/Play call anywhere; the only way L0 expresses an alert is a status-light color change (<code>PinTile.Update</code>)</td><td>✅ audit passed</td></tr><tr><td>3</td><td>Carries no action that requires confirmation</td><td>L0 has no action entry (no <code>ActionRunner</code> reference); drill-down only</td><td>✅ audit passed</td></tr><tr><td>4</td><td>Never steals focus, never appears in Alt-Tab or the taskbar</td><td><code>WS_EX_NOACTIVATE + WS_EX_TOOLWINDOW</code>, <code>IsShownInSwitchers=false</code>, topmost, and drag/hover all use pointer events (no activation)</td><td>✅ audit passed (real-machine recheck belongs to B-803)</td></tr></tbody></table><h2 id="critical-expression-supplement-to-invariant-2" tabindex="-1">Critical expression (supplement to invariant 2) <a class="header-anchor" href="#critical-expression-supplement-to-invariant-2" aria-label="Permalink to &quot;Critical expression (supplement to invariant 2)&quot;">​</a></h2><ul><li>Current state: Critical only turns the status light red (<code>SeverityPalette.Color(Critical)</code>), with no interruption of any kind.</li><li>The pulse animation (≤1 Hz × intensity) belongs to the <strong>B-707 motion system</strong> scope (RFC §6.2.8: reduced mode defaults to pulsing). Once B-707 lands, this table is re-checked for &quot;a pulsing light still produces no sound and no dialog&quot;.</li></ul><h2 id="alert-channel-separation" tabindex="-1">Alert channel separation <a class="header-anchor" href="#alert-channel-separation" aria-label="Permalink to &quot;Alert channel separation&quot;">​</a></h2><ul><li>Alerts always go through <code>NotificationEngine</code> (B-502) → Toast and sound are driven by the rule table; L0 does not subscribe to <code>NotificationRaised</code> and never touches <code>INotificationSink</code> (grep evidence above).</li></ul><h2 id="real-machine-checklist-checked-off-when-b-803-runs" tabindex="-1">Real-machine checklist (checked off when B-803 runs) <a class="header-anchor" href="#real-machine-checklist-checked-off-when-b-803-runs" aria-label="Permalink to &quot;Real-machine checklist (checked off when B-803 runs)&quot;">​</a></h2><ul><li>[ ] Inject a Critical state: L0 only changes color (pulses after B-707), with no dialog or sound interruption; the Toast is still emitted by the notification engine as usual</li><li>[ ] Network disconnected: the tile shows a gray hollow light + Last update (B-704), with no exception dialog; it resets automatically on recovery</li><li>[ ] Click a tile → L2 opens and takes focus; it closes automatically on focus loss; ESC closes it</li><li>[ ] Neither the Alt-Tab list nor the taskbar shows the L0 host; clicking a tile does not interrupt the current input focus</li><li>[ ] Drag flush against a screen edge → collapses to a strip; hover expands, a click on the drop target pops back to expanded, a click while expanded drills into L2; releasing near an edge does not collapse by mistake (B-703 + the reversible-collapse revision)</li></ul>',10)])])}const b=t(i,[["render",r]]);export{p as __pageData,b as default};
